extractor:
function extract(frame, memory, info) {
  memory = memory || {};
  info = info || {};
  var lag = typeof info.lagMs === 'number' && info.lagMs > 0 ? info.lagMs : 0;
  var now = typeof info.nowMs === 'number' ? info.nowMs : null;
  var P = null, G = null, obs = [], over = false;
  for (var i = 0; i < frame.length; i++) {
    var d = frame[i];
    if (d.k === 'text') { if (/game\s*over/i.test(d.t || '')) over = true; continue; }
    if (d.k === 'rect') { if (d.w > 0 && d.h > 0 && d.w < 300 && d.h < 100) obs.push({ kind: 'unknown', x: d.x, y: d.y, w: d.w, h: d.h }); continue; }
    if (d.k !== 'img') continue;
    var m = /:([^,]*),([^,]*),([^,]*),([^,]*)$/.exec(d.s || '');
    var sx = m ? +m[1] : NaN, sy = m ? +m[2] : NaN;
    if (sy >= 50 || d.w >= 300) { if (d.w >= 300 && G === null) G = d.y + d.h + 1; continue; }
    if (d.w === 10 && d.h === 13 && d.y < 40) continue; // score digits
    if (sx >= 645 && sx < 655 && d.w <= 10) continue; // night-mode stars (sky decoration)
    if (sy === 15 && sx >= 655) { over = true; continue; }
    if (sx === 2 && sy === 2) { over = true; continue; }
    if (sx >= 848 && sy <= 2 && d.h >= 20) {
      var st = (sx >= 1112 || d.w > 50) ? 'duck' : sx === 1068 ? 'crashed' : sx === 848 ? 'jump' : 'run';
      if (st === 'crashed') over = true;
      P = { x: d.x, y: d.y, w: d.w, h: d.h, state: st };
      continue;
    }
    if (sy === 2 && (sx === 86 || (sx >= 484 && sx < 655))) continue; // clouds, moon
    var kind = sy !== 2 ? 'unknown' : (sx >= 228 && sx < 332) ? 'cactus_small' : (sx >= 332 && sx < 484) ? 'cactus_large' : (sx >= 134 && sx < 228) ? 'bird' : 'unknown';
    obs.push({ kind: kind, x: d.x, y: d.y, w: d.w, h: d.h });
  }
  if (over) { memory.v = null; memory.live = null; memory.liveNow = null; memory.prevAlt = null; }
  // on a key press the game redraws the dino alone (no ground line, no obstacles): keep the last ground line
  if (G !== null) memory.G = G;
  else if (typeof memory.G === 'number') G = memory.G;
  else { G = P ? P.y + P.h : 0; for (var j = 0; j < obs.length; j++) G = Math.max(G, obs[j].y + obs[j].h); }
  var pl = P ? P.x : 0;
  var live = obs.filter(function (o) { return o.x + o.w > pl && (o.kind === 'bird' || G - o.y - o.h < 60); }).sort(function (a, b) { return a.x - b.x; });
  if (typeof memory.v !== 'number') memory.v = 0.36;
  if (typeof memory.P !== 'number') memory.P = 50;
  // decision period (game ms between frames we are asked about)
  var dt = (now !== null && typeof memory.lastNow === 'number') ? now - memory.lastNow : null;
  if (dt !== null && dt > 0 && dt < 400) memory.P = memory.P * 0.7 + dt * 0.3;
  memory.lastNow = now;
  // el: game ms since the last frame that showed the obstacles
  var prev = memory.live || [], el = (now !== null && typeof memory.liveNow === 'number') ? now - memory.liveNow : 0;
  var fresh = true;
  if (!over && live.length === 0 && prev.length > 0 && el >= 0 && el < 400) {
    // the dino drawn alone: move the last frame's obstacles on at their speed
    var pred = [];
    for (var c = 0; c < prev.length; c++) {
      var po = prev[c], px = po.x - (po.kind === 'bird' && po.v ? po.v : memory.v) * el;
      if (px + po.w > pl) pred.push({ kind: po.kind, x: px, y: po.y, w: po.w, h: po.h, v: po.v });
    }
    if (pred.length > 0) { live = pred; fresh = false; }
  }
  if (fresh) {
    // speed (px per game ms): follow each obstacle from where it was first seen
    var best = null, maxSh = el > 0 ? el * 1.2 + 12 : 60;
    for (var a = 0; a < live.length; a++) {
      var o = live[a], mt = null;
      for (var b = 0; b < prev.length; b++) {
        var p = prev[b], sh = p.x - o.x;
        if (p.kind === o.kind && p.w === o.w && Math.abs(p.y - o.y) <= 2 && sh >= 0 && sh <= maxSh && (mt === null || sh < mt.x - o.x)) mt = p;
      }
      o.x0 = mt ? mt.x0 : o.x; o.t0 = mt ? mt.t0 : now;
      if (now !== null && o.t0 !== null && now - o.t0 >= 100 && o.x0 > o.x) {
        o.v = (o.x0 - o.x) / (now - o.t0);
        if (o.kind !== 'bird' && (best === null || o.t0 < best.t0)) best = o;
      }
    }
    if (best) memory.v = Math.max(0.3, Math.min(1, memory.v * 0.5 + best.v * 0.5));
    memory.live = live.map(function (o) { return { kind: o.kind, x: o.x, y: o.y, w: o.w, h: o.h, x0: o.x0, t0: o.t0, v: o.v }; });
    memory.liveNow = now;
  }
  var v = memory.v, Pd = memory.P, S = lag + 8, M = 20;
  // full jump (key held while rising), simulated per 16ms frame with the game's physics
  var traj = [], ja = 0, ju = 10 + v / 0.6, up = false;
  for (var f = 0; f < 90; f++) {
    ja += Math.round(ju * 0.96); ju -= 0.576;
    if (ja > 30) up = true;
    if (up && ja > 63 && ju > 5) ju = 5;
    if (ja <= 0) break;
    traj.push(ja);
  }
  var AIR = (traj.length + 1) * 16;
  function win(h) {
    var lo = null, hi = null;
    for (var k = 0; k < traj.length; k++) if (traj[k] >= h) { if (lo === null) lo = (k + 1) * 16; hi = (k + 1) * 16; }
    return lo === null ? null : [lo, hi];
  }
  // tIn/tOut: ms from now until the obstacle enters/leaves the dino's body columns
  // E/L: earliest/latest jump start (ms from now) that clears it
  var list = live.map(function (o) {
    var bird = o.kind === 'bird', bottom = Math.round(G - o.y - o.h), top = Math.round(G - o.y);
    var ov = bird && o.v ? Math.max(0.2, Math.min(1.2, o.v)) : v;
    var e = { kind: o.kind, dx: Math.round(o.x - pl - 44), top: top, bottom: bottom, overhead: bird && bottom >= 45, duckable: bird && bottom >= 18 && bottom < 45, tIn: (o.x - pl - (bird ? 40 : 34)) / ov, tOut: (o.x + o.w - pl - 2) / ov, H: top - 4 };
    var w = win(e.H);
    e.E = w ? e.tOut - w[1] + M : Infinity;
    e.L = w ? e.tIn - w[0] - M : -Infinity;
    return e;
  });
  // a high bird passing over the dino while it is in the air hits its head: keep the jump clear of each one
  function clearOfBirds(E, L) {
    for (var r = 0; r < list.length; r++) {
      var bd = list[r];
      if (!bd.overhead || bd.tOut <= 0) continue;
      var wb = win(Math.max(1, bd.bottom - 36));
      if (!wb) continue;
      var a1 = bd.tIn - wb[1] - M, a2 = bd.tOut - wb[0] + M;
      if (L < a1 || E > a2) continue;
      if (a1 >= Math.max(E, S)) L = a1;
      else if (a2 <= L) E = a2;
    }
    return [E, L];
  }
  var th = null, nx = null;
  for (var q = 0; q < list.length; q++) {
    if (list[q].overhead || list[q].tOut <= S) continue;
    if (th === null) th = list[q]; else { nx = list[q]; break; }
  }
  var threat = null;
  if (th) {
    threat = { kind: th.kind, dx: th.dx, top: th.top, bottom: th.bottom, duckable: th.duckable, contact: th.tIn <= S ? 'overlapping' : th.tIn <= S + Pd + 40 ? 'near' : 'far', jumpTiming: null };
    if (!th.duckable) {
      var E = th.E, L = th.L;
      if (nx && nx.duckable) L = Math.min(L, Math.max(E, nx.tIn - AIR - Pd - S));
      else if (nx) {
        // one jump over both, or jump early enough to land and jump again
        var Lc = nx.L - AIR - Pd - S, w2 = win(Math.max(th.H, nx.H));
        var Eb = w2 ? nx.tOut - w2[1] + M : Infinity, Lb = w2 ? th.tIn - w2[0] - M : -Infinity;
        if (Lb >= Eb && (Lc < E || Lb - Eb >= 40)) { E = Eb; L = Lb; }
        else L = Math.min(L, Math.max(E, Lc));
      }
      var cb = clearOfBirds(E, L); E = cb[0]; L = cb[1];
      threat.jumpTiming = S > L ? 'late' : S + Pd > L ? 'ok' : S < E ? 'early' : S >= (E + L) / 2 - Pd / 2 ? 'ok' : 'early';
    }
  }
  var alt = P ? Math.max(0, Math.round(G - P.y - P.h)) : 0;
  var air = !!P && P.state !== 'duck' && (alt > 1 || P.state === 'jump');
  var rising = air && (typeof memory.prevAlt !== 'number' || alt >= memory.prevAlt);
  memory.prevAlt = air ? alt : 0;
  return {
    over: over,
    player: P ? { air: air, rising: rising, ducking: P.state === 'duck' } : null,
    threat: threat,
    obstacles: list.slice(0, 3).map(function (e) { return { kind: e.kind, dx: e.dx, top: e.top, bottom: e.bottom }; })
  };
}

teacher:
function teach(state) {
  if (!state) return 'NOOP';
  // 1. Game over -> JUMP restarts
  if (state.over === true) return 'JUMP';
  var p = state.player || {}, t = state.threat;
  // 2. In the air: hold JUMP while rising (full-height jump), release while falling
  if (p.air === true) return (p.rising === true && t && t.duckable !== true) ? 'JUMP' : 'NOOP';
  // 3. No threat -> NOOP
  if (!t) return 'NOOP';
  // 4. Bird at head height -> DUCK once it is near
  if (t.duckable === true) return t.contact === 'far' ? 'NOOP' : 'DUCK';
  // 5. Jump timing ok or late -> JUMP
  if (t.jumpTiming === 'ok' || t.jumpTiming === 'late') return 'JUMP';
  // 6. Otherwise (early) -> wait
  return 'NOOP';
}
